/// <summary>
/// Extension of CustVendNettingRuleQueryBuilder to support Metcash custom netting sequence by invoice number.
/// </summary>
[ExtensionOf(classStr(CustVendNettingRuleQueryBuilder))]
final class METCustVendNettingRuleQueryBuilder_Extension
{
    private boolean useBuildQuery;
    private Set     processedCreditPairs = new Set(Types::Int64);
    private Set     processedDebitPairs  = new Set(Types::Int64);

    // Run identifier to tag inserted rows for isolation and cleanup.
    // Orchestration may call setCurrentRunId(runId) before invoking the netting run.
    private static guid currentRunId;

}

Method.Source:
/// <summary>
/// Set the current run identifier for tagging inserted reference rows.
/// </summary>
/// <param name = "_runId">guid</param>
public static void setCurrentRunId(guid _runId)
{
    currentRunId = _runId;
}

/// <summary>
/// Get the current run identifier.
/// </summary>
/// <returns>guid</returns>
public static guid getCurrentRunId()
{
    return currentRunId;
}

/// <summary>
/// Cleanup all reference rows for a run. Call after netting run completes.
/// </summary>
public static void cleanupRefTableForRun(guid _runId)
{
    METNettingTransCustVendRefTable ref;

    if (!_runId)
    {
        return;
    }

    ttsBegin;
    delete_from ref
        where ref.ExecutionId == strFmt('%1', _runId);
    ttsCommit;
}

/// <summary>
/// Extension of buildQueryForDebit to support METByInvoiceNumber sequence.
/// </summary>
/// <param name = "_nettingPair">CustVendNettingPair</param>
/// <param name = "_currencyCode">CurrencyCode</param>
/// <param name = "_sequence">CustVendNettingRuleNettingSequence</param>
/// <param name = "_isCreditDebitNote">boolean</param>
/// <param name = "_parameter">NettingRuleProcessParameter</param>
/// <returns>Debit query</returns>
public Query buildQueryForDebit(CustVendNettingPair _nettingPair,
    CurrencyCode _currencyCode,
    CustVendNettingRuleNettingSequence _sequence,
    boolean _isCreditDebitNote,
    NettingRuleProcessParameter _parameter)
{
    Query query;

    if (_sequence == CustVendNettingRuleNettingSequence::METByInvoiceNumber)
    {
        // ensure RunId exists for this process (prefer orchestration to set)
        if (!currentRunId)
        {
            currentRunId = newGuid();
        }

        // Populate reference table for vendor (credit) side
        this.insertNettingRefData(_nettingPair, true, _currencyCode);
    }

    query = next buildQueryForDebit(_nettingPair, _currencyCode, _sequence, _isCreditDebitNote, _parameter);

    if (_sequence == CustVendNettingRuleNettingSequence::METByInvoiceNumber)
    {
        TableId debitTable = CustVendNettingRuleQueryBuilder::metGetDataSourceTableId(_nettingPair.DebitAccountType);
        TableId refTable   = tableNum(METNettingTransCustVendRefTable);

        QueryBuildDataSource qbdsDebit = query.dataSourceNo(1);
        QueryBuildDataSource qbdsRef   = qbdsDebit.addDataSource(refTable);

        qbdsRef.relations(false);
        qbdsRef.joinMode(JoinMode::ExistsJoin);

        // Link debit.Invoice -> ref.Invoice
        qbdsRef.addLink(
            fieldName2Id(debitTable, 'Invoice'),
            fieldName2Id(refTable, 'Invoice'));

        // Restrict ref rows to vendor/account/company/type and current run
        qbdsRef.addRange(fieldName2Id(refTable, 'AccountNum')).value(queryValue(_nettingPair.CreditAccountNum));
        qbdsRef.addRange(fieldName2Id(refTable, 'ExecutionId')).value(queryValue(strFmt('%1', currentRunId)));
    }

    return query;
}

/// <summary>
/// Extension of buildQueryForCredit to support METByInvoiceNumber sequence.
/// </summary>
/// <param name = "_nettingPair">CustVendNettingPair</param>
/// <param name = "_currencyCode">CurrencyCode</param>
/// <param name = "_sequence">CustVendNettingRuleNettingSequence</param>
/// <param name = "_isCreditDebitNote">boolean</param>
/// <param name = "_parameter">NettingRuleProcessParameter</param>
/// <returns>Credit query</returns>
public Query buildQueryForCredit(CustVendNettingPair _nettingPair,
    CurrencyCode _currencyCode,
    CustVendNettingRuleNettingSequence _sequence,
    boolean _isCreditDebitNote,
    NettingRuleProcessParameter _parameter)
{
    Query query;

    if (_sequence == CustVendNettingRuleNettingSequence::METByInvoiceNumber)
    {
        if (!currentRunId)
        {
            currentRunId = newGuid();
        }

        // Populate reference table for customer (debit) side
        this.insertNettingRefData(_nettingPair, false, _currencyCode);
    }

    query = next buildQueryForCredit(_nettingPair, _currencyCode, _sequence, _isCreditDebitNote, _parameter);

    if (_sequence == CustVendNettingRuleNettingSequence::METByInvoiceNumber)
    {
        TableId creditTable = CustVendNettingRuleQueryBuilder::metGetDataSourceTableId(_nettingPair.CreditAccountType);
        TableId refTable    = tableNum(METNettingTransCustVendRefTable);

        QueryBuildDataSource qbdsCredit = query.dataSourceNo(1);
        QueryBuildDataSource qbdsRef    = qbdsCredit.addDataSource(refTable);

        qbdsRef.relations(false);
        qbdsRef.joinMode(JoinMode::ExistsJoin);

        // Link credit.Invoice -> ref.Invoice
        qbdsRef.addLink(
            fieldName2Id(creditTable, 'Invoice'),
            fieldName2Id(refTable, 'Invoice'));

        // Restrict ref rows to customer/account/company/type and current run
        qbdsRef.addRange(fieldName2Id(refTable, 'AccountNum')).value(queryValue(_nettingPair.DebitAccountNum));
        qbdsRef.addRange(fieldName2Id(refTable, 'ExecutionId')).value(queryValue(strFmt('%1', currentRunId)));
    }

    return query;
}

/// <summary>
/// Extension of applySequence to support METByInvoiceNumber sequence.
/// </summary>
/// <param name = "_qbds">QueryBuildDataSource</param>
/// <param name = "_dataSourceTableId">TableId</param>
/// <param name = "_sequence">CustVendNettingRuleNettingSequence</param>
/// <param name = "_isAmountPositive">boolean</param>
protected void applySequence(QueryBuildDataSource _qbds, TableId _dataSourceTableId, CustVendNettingRuleNettingSequence _sequence, boolean _isAmountPositive)
{
    next applySequence(_qbds, _dataSourceTableId, _sequence, _isAmountPositive);

    if (_sequence == CustVendNettingRuleNettingSequence::METByInvoiceNumber)
    {
        // Sort by InvoiceId ascending for Metcash custom sequence
        _qbds.addOrderByField(fieldName2Id(_dataSourceTableId, 'Invoice'));
    }
}

/// <summary>
/// Insert reference rows for the netting pair.
/// When _isCreditSide is true: insert vendor (credit) rows to the ref table.
/// When _isCreditSide is false: insert customer (debit) rows to the ref table.
/// Uses currentRunId (ExecutionId) to tag rows for isolation and cleanup.
/// Idempotent per pair+run.
/// </summary>
private void insertNettingRefData(CustVendNettingPair _nettingPair, boolean _isCreditSide, CurrencyCode _currencyCode)
{
    str                             runIdStr            = strFmt('%1', currentRunId);
    RecId                           pairRecId           = _nettingPair.RecId;
    VendNettingTransView            vendNettingTransView;
    CustNettingTransTotalView       custNettingTransTotalView;
    METNettingTransCustVendRefTable existingRef, deleteRef, insertRef;
    RecordInsertList                recordInsertList    = new RecordInsertList(tableNum(METNettingTransCustVendRefTable), true, true);

    if (_isCreditSide)
    {
        // Check for rows already inserted for this pair/run
        select firstonly RecId from existingRef
            where existingRef.AccountNum == _nettingPair.CreditAccountNum
               && existingRef.LegalEntity == _nettingPair.CreditCompany
               && existingRef.NettingTransType == METNettingTransType::Credit
               && existingRef.ExecutionId == runIdStr;

        if (existingRef.RecId)
        {
            return;
        }

        ttsBegin;

        // Cleanup: remove any rows with empty ExecutionId for this account
        delete_from deleteRef
            where deleteRef.AccountNum == _nettingPair.DebitAccountNum
               && (deleteRef.ExecutionId == '' || deleteRef.ExecutionId == null);

        // delete previous refs for this account/company/type for this pair/run only
        delete_from deleteRef
            where deleteRef.AccountNum == _nettingPair.DebitAccountNum
               && deleteRef.LegalEntity == _nettingPair.CreditCompany
               && deleteRef.NettingTransType == METNettingTransType::Credit
               && deleteRef.ExecutionId == runIdStr;

        // Insert vendor open transactions using RecordInsertList
        changecompany(_nettingPair.DebitCompany)
        {
            while select Invoice, AccountNum, DataAreaId, AmountCur from vendNettingTransView
                where vendNettingTransView.AccountNum == _nettingPair.DebitAccountNum
                   && vendNettingTransView.Invoice != ''
                   && (!_currencyCode || _currencyCode == '' || vendNettingTransView.CurrencyCode == _currencyCode)
            {
                insertRef.clear();
                insertRef.Invoice            = vendNettingTransView.Invoice;
                insertRef.AccountNum         = vendNettingTransView.AccountNum;
                insertRef.LegalEntity        = _nettingPair.CreditCompany;
                insertRef.AmountCurCredit    = vendNettingTransView.AmountCur;
                insertRef.NettingTransType   = METNettingTransType::Credit;
                insertRef.ExecutionId        = runIdStr;
                insertRef.NettingExecutionId = pairRecId;
                recordInsertList.add(insertRef);
            }
        }

        recordInsertList.insertDatabase();

        ttsCommit;

        processedCreditPairs.add(_nettingPair.RecId);
    }
    else
    {
        // debit side (customer)
        select firstonly RecId from existingRef
            where existingRef.AccountNum == _nettingPair.CreditAccountNum
               && existingRef.LegalEntity == _nettingPair.DebitCompany
               && existingRef.NettingTransType == METNettingTransType::Debit
               && existingRef.ExecutionId == runIdStr;

        if (existingRef.RecId)
        {
            return;
        }

        ttsBegin;

        // Cleanup: remove any rows with empty ExecutionId for this account
        delete_from deleteRef
            where deleteRef.AccountNum == _nettingPair.CreditAccountNum
               && (deleteRef.ExecutionId == '' || deleteRef.ExecutionId == null);

        // delete previous refs for this account/company/type for this pair/run only
        delete_from deleteRef
            where deleteRef.AccountNum == _nettingPair.CreditAccountNum
               && deleteRef.LegalEntity == _nettingPair.DebitCompany
               && deleteRef.NettingTransType == METNettingTransType::Debit
               && deleteRef.ExecutionId == runIdStr;

        // Insert customer open transactions using RecordInsertList
        changecompany(_nettingPair.CreditCompany)
        {
            while select Invoice, AccountNum, DataAreaId, AmountCur from custNettingTransTotalView
                where custNettingTransTotalView.AccountNum == _nettingPair.CreditAccountNum
                   && custNettingTransTotalView.Invoice != ''
                   && (!_currencyCode || _currencyCode == '' || custNettingTransTotalView.CurrencyCode == _currencyCode)
            {
                insertRef.clear();
                insertRef.Invoice            = custNettingTransTotalView.Invoice;
                insertRef.AccountNum         = custNettingTransTotalView.AccountNum;
                insertRef.LegalEntity        = _nettingPair.DebitCompany;
                insertRef.AmountCurDebit     = custNettingTransTotalView.AmountCur;
                insertRef.NettingTransType   = METNettingTransType::Debit;
                insertRef.ExecutionId        = runIdStr;
                insertRef.NettingExecutionId = pairRecId;
                recordInsertList.add(insertRef);
            }
        }

        recordInsertList.insertDatabase();

        ttsCommit;

        processedDebitPairs.add(_nettingPair.RecId);
    }
}

/// <summary>
/// Custom method to get the data source table for a given account type.
/// </summary>
/// <param name = "_accountType">LedgerJournalACType</param>
/// <returns>TableId</returns>
public static TableId metGetDataSourceTableId(LedgerJournalACType _accountType)
{
    TableId tableId;

    switch (_accountType)
    {
        case LedgerJournalACType::Vend:
            tableId = tableNum(VendNettingTransView);
            break;

        case LedgerJournalACType::Cust:
            tableId = tableNum(CustNettingTransTotalView);
            break;

        default:
            throw Error(Error::wrongUseOfFunction(funcName()));
    }

    return tableId;
}
